import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Route> routingTable = Arrays.asList(
            new Route("10.0.0.0/8", "USA Datacenter"),
            new Route("10.10.0.0/16", "India Region"),
            new Route("10.10.5.0/24", "Mumbai Datacenter")
        );
        String defaultRoute = "Default Gateway";

        System.out.println("10.10.5.44 -> " + longestPrefixMatch("10.10.5.44", routingTable, defaultRoute));
        System.out.println("10.20.1.1 -> " + longestPrefixMatch("10.20.1.1", routingTable, defaultRoute));
        System.out.println("8.8.8.8 -> " + longestPrefixMatch("8.8.8.8", routingTable, defaultRoute));
    }

    static class Route {
        long network;
        int prefixLen;
        String nextHop;
        Route(String cidr, String nextHop) {
            String[] parts = cidr.split("/");
            this.network = ipToLong(parts[0]);
            this.prefixLen = Integer.parseInt(parts[1]);
            this.nextHop = nextHop;
        }
    }

    static long ipToLong(String ip) {
        String[] octets = ip.split("\\.");
        long result = 0;
        for (String octet : octets) {
            result = (result << 8) | Long.parseLong(octet);
        }
        return result;
    }

    static long maskFor(int prefixLen) {
        if (prefixLen == 0) return 0;
        return (0xFFFFFFFFL << (32 - prefixLen)) & 0xFFFFFFFFL;
    }

    // Among every route whose network matches the destination under its own mask,
    // the one with the longest (most specific) prefix length wins.
    static String longestPrefixMatch(String destinationIp, List<Route> routingTable, String defaultRoute) {
        long destination = ipToLong(destinationIp);
        String best = null;
        int bestPrefixLen = -1;

        for (Route route : routingTable) {
            long mask = maskFor(route.prefixLen);
            if ((destination & mask) == (route.network & mask)) {
                if (route.prefixLen > bestPrefixLen) {
                    bestPrefixLen = route.prefixLen;
                    best = route.nextHop;
                }
            }
        }

        return best != null ? best : defaultRoute;
    }
}

