class Route:
    def __init__(self, cidr, next_hop):
        network_str, prefix_len_str = cidr.split("/")
        self.network = ip_to_int(network_str)
        self.prefix_len = int(prefix_len_str)
        self.next_hop = next_hop


def ip_to_int(ip):
    octets = ip.split(".")
    result = 0
    for octet in octets:
        result = (result << 8) | int(octet)
    return result


def mask_for(prefix_len):
    if prefix_len == 0:
        return 0
    return (0xFFFFFFFF << (32 - prefix_len)) & 0xFFFFFFFF


# Among every route whose network matches the destination under its own mask,
# the one with the longest (most specific) prefix length wins.
def longest_prefix_match(destination_ip, routing_table, default_route):
    destination = ip_to_int(destination_ip)
    best = None
    best_prefix_len = -1

    for route in routing_table:
        mask = mask_for(route.prefix_len)
        if (destination & mask) == (route.network & mask):
            if route.prefix_len > best_prefix_len:
                best_prefix_len = route.prefix_len
                best = route.next_hop

    return best if best is not None else default_route


def main():
    routing_table = [
        Route("10.0.0.0/8", "USA Datacenter"),
        Route("10.10.0.0/16", "India Region"),
        Route("10.10.5.0/24", "Mumbai Datacenter"),
    ]
    default_route = "Default Gateway"

    print("10.10.5.44 ->", longest_prefix_match("10.10.5.44", routing_table, default_route))
    print("10.20.1.1 ->", longest_prefix_match("10.20.1.1", routing_table, default_route))
    print("8.8.8.8 ->", longest_prefix_match("8.8.8.8", routing_table, default_route))


if __name__ == "__main__":
    main()

