#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cstdint>
using namespace std;

uint32_t ipToInt(const string& ip) {
    uint32_t result = 0;
    stringstream ss(ip);
    string octet;
    while (getline(ss, octet, '.')) {
        result = (result << 8) | static_cast<uint32_t>(stoul(octet));
    }
    return result;
}

struct Route {
    uint32_t network;
    int prefixLen;
    string nextHop;
    Route(const string& cidr, const string& nextHop) : nextHop(nextHop) {
        size_t slashPos = cidr.find('/');
        network = ipToInt(cidr.substr(0, slashPos));
        prefixLen = stoi(cidr.substr(slashPos + 1));
    }
};

uint32_t maskFor(int prefixLen) {
    if (prefixLen == 0) return 0;
    return static_cast<uint32_t>(0xFFFFFFFFu << (32 - prefixLen));
}

// Among every route whose network matches the destination under its own mask,
// the one with the longest (most specific) prefix length wins.
string longestPrefixMatch(const string& destinationIp, const vector<Route>& routingTable, const string& defaultRoute) {
    uint32_t destination = ipToInt(destinationIp);
    string best = "";
    int bestPrefixLen = -1;

    for (const auto& route : routingTable) {
        uint32_t mask = maskFor(route.prefixLen);
        if ((destination & mask) == (route.network & mask)) {
            if (route.prefixLen > bestPrefixLen) {
                bestPrefixLen = route.prefixLen;
                best = route.nextHop;
            }
        }
    }

    return bestPrefixLen != -1 ? best : defaultRoute;
}

int main() {
    vector<Route> routingTable = {
        Route("10.0.0.0/8", "USA Datacenter"),
        Route("10.10.0.0/16", "India Region"),
        Route("10.10.5.0/24", "Mumbai Datacenter"),
    };
    string defaultRoute = "Default Gateway";

    cout << "10.10.5.44 -> " << longestPrefixMatch("10.10.5.44", routingTable, defaultRoute) << endl;
    cout << "10.20.1.1 -> " << longestPrefixMatch("10.20.1.1", routingTable, defaultRoute) << endl;
    cout << "8.8.8.8 -> " << longestPrefixMatch("8.8.8.8", routingTable, defaultRoute) << endl;

    return 0;
}
